import {AREAS,BUILDINGS,ITEMS,NPCS,QUESTS,IDENTITIES,SEASONS,WEATHER,WEEKDAYS,calendar,level,building,COATS,HAIRS,furnitureFor} from './content.js';
import {ageOf,isOpen,relationship} from './simulation.js';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const clock=m=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(Math.floor(m%60)).padStart(2,'0');
const btn=(text,action,data='',disabled=false)=>`<button class="action-button" data-act="${action}" ${data}${disabled?' disabled':''}>${text}</button>`;
const row=(name,note,action)=>`<div class="action-row"><div class="action-copy"><b>${name}</b><small>${note}</small></div>${action}</div>`;
const desc=text=>`<p class="panel-description">${text}</p>`;
const divider=text=>`<div class="section-divider">${text}</div>`;
const population=(s,area)=>{const here=s.npcs.filter(n=>n.area===area&&!n.transit);return here.filter(n=>!n.inside).length+' 位在街上 · '+here.filter(n=>n.inside).length+' 位在屋里';};
const skillNames={gardening:'园艺',knowledge:'学识',career:'职业',creativity:'创作',fishing:'垂钓'};
export function renderPanel(s,kind,data={},settings={},metrics={}){
  const p=s.player,cal=calendar(s.day);let title='',caption='YOUR LITTLE TOWN',html='';
  if(kind==='bag'){title='随身的小日常';caption='A POCKETFUL OF DAYS';html=desc('食物会恢复饱腹；花与小礼物，可以送给慢慢熟悉的邻居。');for(const [id,n]of Object.entries(p.inventory)){if(!n||!ITEMS[id])continue;const i=ITEMS[id];html+=`<div class="action-row"><span class="bag-icon">${i.icon}</span><div class="action-copy"><b>${i.name} <span style="color:#aaa88b">× ${n}</span></b><small>${i.food?'饱腹 +'+i.food+(i.energy?' · 体力 +'+i.energy:''):i.note??'可以送礼或在农庄出售'}</small></div>${i.food?btn('慢慢吃','eat',`data-item="${id}"`):''}</div>`;}html+=divider('生活小贴士')+desc('浇水壶和钓竿是小屋附带的工具，不占背包。点菜畦或水边钓点，就可以使用。');}
  if(kind==='map'){title='今天，往哪里走？';caption='FIVE PLACES TO CALL HOME';html=desc('选择目的地，会沿着街区的路口步行前往。走远一点，也许会遇见新的日常。');for(const [id,a]of Object.entries(AREAS)){html+=`<div class="map-card${p.area===id?' current':''}" style="--district-color:${a.color}"><div class="map-name"><span class="map-icon">${a.icon}</span><h3>${a.name}</h3></div><p>${a.subtitle}<br>${population(s,id)}</p><button class="action-button" data-travel="${id}">${p.area===id?'在这里走走':'步行前往 →'}</button>${p.area===id?'<small>你在这里</small>':''}<div class="inline-actions">${BUILDINGS.filter(b=>b.area===id&&(id!=='center'||['bakery','cafe','books','flowers','post'].includes(b.id))).map(b=>`<button class="small-button" data-destination="${b.id}">${b.name}</button>`).join('')}</div></div>`;}}
  if(kind==='people'){title='熟悉的人，越来越多';caption='THE PEOPLE WE MEET';html=desc(AREAS[p.area].name+'：'+population(s,p.area)+'。<br>与你同处一地的邻居会排在前面；雨雪天也可以进屋找朋友。');const rank=n=>{const live=s.npcs.find(x=>x.id===n.id);return !live.transit&&live.area===p.area?(live.inside===p.inside?0:1):2;};const sorted=[...NPCS].sort((a,b)=>rank(a)-rank(b)||s.relations[b.id].trust-s.relations[a.id].trust);for(const n of sorted){const r=s.relations[n.id],live=s.npcs.find(x=>x.id===n.id);html+=`<div class="resident-row"><span class="resident-avatar" style="background:${COATS[n.index%6]}">${n.name.slice(0,1)}</span><div class="resident-info"><strong>${n.name} <em>· ${n.role}</em></strong><small>${relationship(r)} · ${live.transit?'在路上':building(live.inside)?.name??AREAS[live.area].name}</small></div><button class="small-button" data-person="${n.id}">认识一下</button></div>`;}}
  if(kind==='person'||kind==='npc'){
    const n=NPCS.find(n=>n.id===(data.id??data.npc));if(!n)return {title:'邻居出门了',caption,html:desc('再去别处看看吧。')};const r=s.relations[n.id],live=s.npcs.find(x=>x.id===n.id),near=!live.transit&&live.area===p.area&&live.inside===p.inside&&(p.inside||Math.hypot(live.x-p.x,live.z-p.z)<3.3);title=n.name;caption='A FRIEND, A LITTLE CLOSER';html=`<div class="person-hero"><div class="person-symbol">${n.baseAge<18?'♧':'♡'}</div><h3>${n.name}</h3><p>${n.role} · ${ageOf(s,n.baseAge)} 岁 · ${n.personality}</p><div class="relationship-track">${Array.from({length:5},(_,i)=>`<span class="${r.trust>=i*20+4?'filled':''}">♡</span>`).join('')}</div><p style="margin-top:9px">${relationship(r)} · 信任 ${Math.floor(r.trust)} · 亲近 ${Math.floor(r.affinity)}</p></div>`;
    if(data.message)html+=`<div class="event-note">${esc(data.message)}</div>`;html+=desc(`${esc(live.task)}。<br>${live.transit?'目前在路上，稍后再看看。':'此刻在 '+esc(building(live.inside)?.name??AREAS[live.area].name)}。`);
    if(!near)html+=`<button class="action-button strong wide" data-findnpc="${n.id}">沿着地图去找 TA →</button>`;
    else{html+=row('聊聊今天','8 分钟 · 每天一次，慢慢熟悉',btn(r.lastChat===s.day?'今天聊过了':'打个招呼','chat',`data-npc="${n.id}"`,r.lastChat===s.day));html+=row('帮一点小忙','30 分钟 · 体力 −8 · 获得 24 币',btn('一起做','help',`data-npc="${n.id}"`,r.lastHelp===s.day));html+=row('约一个傍晚','朋友会记得你的约定，也会记得失约。',btn('邀请喝茶','invite',`data-npc="${n.id}"`,r.trust<12||r.lastInvite===s.day));if(r.promise?.day===s.day&&!r.promise.done)html+=row('今天 18:00 的约定','慢慢咖啡馆 · 17:30—19:30',btn('一起坐坐','meet',`data-npc="${n.id}"`,p.inside!=='cafe'));if(ageOf(s)>=18&&ageOf(s,n.baseAge)>=18)html+=row('认真表达心意','需要信任 40、亲近 25；也可以一直做朋友。',btn(r.stage==='恋人'?'已在交往':'表达心意','romance',`data-npc="${n.id}"`,r.trust<40||r.affinity<25||r.stage==='恋人'));html+=divider('一份小小的心意')+desc('TA 喜欢 '+ITEMS[n.likes].name+'。每天一份就足够了。');for(const [id,count]of Object.entries(p.inventory))if(count>0&&id!=='seed')html+=row(ITEMS[id].name+' × '+count,id===n.likes?'TA 喜欢这一份。':'礼物里，心意最先到达。',btn('送给 TA','gift',`data-npc="${n.id}" data-item="${id}"`,r.lastGift===s.day));}
    if(r.memory.length){html+=divider('你们一起留下的记忆');for(const line of r.memory)html+=`<div class="person-memory">${esc(line)}</div>`;}
  }
  if(kind==='journal'){title='那些小小的回声';caption='THE DAYS WE KEEP';if(s.event)html+=`<div class="event-note">${esc(s.event.text)}${s.event.type==='letter'&&!s.event.claimed?'<div style="margin-top:10px">'+btn('收好来信','letter')+'</div>':''}</div>`;html+=divider('安家小心愿');for(const q of QUESTS)html+=`<div class="quest-row"><b>${s.claimed.includes(q.id)?'✓ ':''}${q.name}</b><p>${q.note}</p>${s.claimed.includes(q.id)?'<span class="done">已收好这份礼物</span>':btn(s.flags[q.id]?'领取 '+q.reward+' 币':'安家礼 '+q.reward+' 币','claim',`data-id="${q.id}"`,!s.flags[q.id])}</div>`;const promises=NPCS.filter(n=>s.relations[n.id].promise?.day===s.day&&!s.relations[n.id].promise.done);if(promises.length){html+=divider('今天的约定');for(const n of promises)html+=desc('18:00 · 与 '+n.name+' 在慢慢咖啡馆见。');}html+=divider('日常手记');for(const j of s.journal.slice(0,35)){const c=calendar(j.day);html+=`<div class="journal-entry"><time>第 ${c.year} 年 · ${SEASONS[c.season]} ${c.date} 日 · ${clock(j.minute)}</time>${esc(j.text)}</div>`;}}
  if(kind==='profile'){title=esc(p.name)+'的日常';caption='A LIFE, SLOWLY GROWING';html=desc('你会在四季中长大。好好吃饭、适当走动和按时休息，会改变身体的状态；熬夜与忙碌也会留下痕迹。');const pairs=[['年龄',ageOf(s)+' 岁'],['起点',IDENTITIES[p.identity]?.name??'小镇居民'],['身体状态',Math.round(p.health)+' / 100'],['生活压力',Math.round(p.stress)+' / 100'],['坚持散步',p.habits.activeDays+' 天'],['深夜未眠',p.habits.lateNights+' 次']];for(const [a,b]of pairs)html+=`<div class="stat-pair"><span>${a}</span><span>${b}</span></div>`;html+=divider('慢慢积累的本领');for(const [key,v]of Object.entries(p.skills)){const l=level(v),base=(l-1)**2*12,next=l*l*12,percent=Math.min(100,(v-base)/(next-base)*100);html+=`<div class="skill-row"><div><span>${skillNames[key]}</span><small>Lv.${l} · ${Math.floor(v)} 经验</small></div><div class="meter"><i style="width:${percent}%"></i></div></div>`;}html+=desc('小镇的一年有 56 天，四季各 14 天。每过一年，你和居民都会长一岁。关闭页面时，生活会停在离开的时刻。');}
  if(kind==='room'){const bd=building(p.inside);title=bd?.name??'小屋';caption='COME IN, STAY A WHILE';if(!bd)return {title,caption,html:''};html=desc('你已经走进屋内。点家具可以使用，也可以在这里选择想做的事。');const type=bd.kind;
    const stock=({bakery:['bread'],cafe:['coffee','bread'],flowers:['flower'],market:['seed','bread','apple','flower'],greenhouse:['seed']})[type];if(stock){html+=divider('今天的柜台');for(const id of stock){const i=ITEMS[id];html+=row(i.name,i.price+' 币'+(i.food?' · 饱腹 +'+i.food:''),btn('买一份','buy',`data-item="${id}"`,!isOpen(s,bd)));}}
    if(type==='home'){html+=row('睡到明天','收好今天，醒来后自动保存。',btn('准备睡觉','sleep'));html+=row('在窗边读书','60 分钟 · 体力 −10 · 学识 +12',btn('翻开书','study'));html+=row('画一点喜欢的东西','60 分钟 · 体力 −12 · 有一份小稿酬',btn('开始创作','paint'));html+=row('一碗蔬菜浓汤','20 分钟 · 萝卜 ×1、蘑菇 ×1',btn('煮一碗','cook'));html+=row('泡个热水澡','25 分钟 · 5 币 · 压力 −12',btn('放松一下','bath'));html+=row('换一个喜欢的模样','发色、衣服和配饰，随时都能改变。','<button class="action-button" data-mirror>照镜子</button>');}
    if(type==='hospital')html+=row('让医生看看','40 分钟 · 最多 55 币，手头紧也能得到照料。',btn('接受诊疗','heal'));
    if(type==='school'||type==='books')html+=row('坐下来学习','60 分钟 · 体力 −10 · 学识 +12',btn('翻开书','study'));
    if(type==='office')html+=row('完成一段工作','120 分钟 · 体力 −22 · 压力 +12<br>9:00—18:00，每天最多两段；年满 18 岁可参加。',btn('认真工作','work',undefined,ageOf(s)<18));
    if(type==='studio')html+=row('用作品记录日常','60 分钟 · 体力 −12 · 获得稿酬',btn('开始创作','paint'));
    if(type!=='home')html+=row('在窗边坐一会儿','20 分钟 · 体力 +15 · 压力 −8',btn('歇一会儿','rest'));
    const residents=s.npcs.filter(n=>!n.transit&&n.inside===bd.id);if(residents.length){html+=divider('屋里的邻居');for(const live of residents){const n=NPCS.find(n=>n.id===live.id);html+=row(n.name+' · '+n.role,live.task,`<button class="action-button" data-person="${n.id}">聊聊天</button>`);}}
    html+=divider('');html+='<button class="action-button wide" data-act="exit">推门出去 →</button>';
  }
  if(kind==='prop'){
    title=data.name;caption='THE LITTLE THINGS THAT MATTER';
    if(data.kind==='plot'){const plot=s.plots[data.index];html=desc(plot.crop?plot.growth>=3?'萝卜已经熟了。弯下腰，收好土地的礼物吧。':`萝卜生长进度 ${plot.growth} / 3 天。<br>${plot.watered||s.weather==='rain'?'今天已经有足够的水。':'今天还没有浇水。每天照料，隔天会长大一点。'}`:'土地还空着，放一颗种子，也放一个小小的期待。');html+=row(plot.crop?'这片土壤正在生长':'种一颗白萝卜',plot.crop?'可以收获时，叶片下会露出白白的萝卜。':'5 分钟 · 种子 ×1 · 体力 −3',btn(plot.growth>=3?'收获':plot.crop?'浇水':'播种',plot.growth>=3?'harvest':plot.crop?'water':'plant',`data-plot="${data.index}"`,plot.crop&&plot.growth<3&&(plot.watered||s.weather==='rain')));}
    if(data.kind==='shipping'){html=desc('把采集、垂钓或种植的收获放进木箱，当场结算小镇币。');for(const [id,n]of Object.entries(p.inventory))if(n&&['turnip','fish','mushroom','apple','shell','flower'].includes(id))html+=row(ITEMS[id].name+' × '+n,'每份 '+Math.round(ITEMS[id].price*(s.event?.type==='market'&&['turnip','apple','flower'].includes(id)?1.2:1))+' 币',btn('全部出售','sell',`data-item="${id}" data-all="true"`));}
    if(data.kind==='fish')html=desc('钓竿是小屋留下的旧物。浮标会替你把时间慢下来。')+row('等一尾月湾小鱼','25 分钟 · 体力 −7 · 不一定每次都上钩。',btn('抛下钓竿','fish'));
    if(data.kind==='forage')html=desc('拿一点点就好，明天自然还会有新的礼物。')+row(data.name,'8 分钟 · 体力 −3 · 每天一次',btn('轻轻采集','forage',`data-id="${data.id}"`,s.daily.forage.includes(data.id)));
    if(data.kind==='rest')html=desc('坐一会儿，让心和身体都松下来。')+row('休息片刻','20 分钟 · 体力 +15 · 压力 −8',btn('坐一会儿','rest'));
    if(data.kind==='board')return renderPanel(s,'journal',{},settings,metrics);
  }
  if(kind==='mirror'){title='今天，想穿什么？';caption='A LITTLE CHANGE, A NEW MOOD';html=desc('喜欢现在的自己，也可以试试一点小变化。');for(const [key,colors,name]of[['coat',COATS,'衣服'],['hair',HAIRS,'发色']]){html+=`<div class="mirror-swatches"><span>${name}</span>${colors.map((c,i)=>`<button style="background:${c}" class="${p[key]===i?'selected':''}" aria-label="${name} ${i+1}" data-appearance="${key}" data-value="${i}"></button>`).join('')}</div>`;}html+=divider('小配饰')+`<div class="inline-actions">${['无配饰','戴眼镜','戴草帽'].map((x,i)=>`<button class="action-button" data-appearance="accessory" data-value="${i}">${x}${p.accessory===i?' ✓':''}</button>`).join('')}</div>`;}
  if(kind==='settings'){title='把节奏，调成喜欢的';caption='MAKE YOURSELF AT HOME';html=`<div class="setting-item"><label>画面模式<small>3D 模型 / 更省电的平面小镇</small></label><select class="setting-select" data-setting="mode"><option value="3d"${settings.mode==='3d'?' selected':''}>立体小镇 · 3D</option><option value="2d"${settings.mode==='2d'?' selected':''}>省电小镇 · 2D</option></select></div><div class="setting-item"><label>立体画质<small>流畅优先时，可关闭阴影</small></label><select class="setting-select" data-setting="quality"><option value="high"${settings.quality==='high'?' selected':''}>精致</option><option value="balanced"${settings.quality==='balanced'?' selected':''}>均衡</option><option value="low"${settings.quality==='low'?' selected':''}>流畅</option></select></div><div class="setting-item"><label>小镇的声音<small>音乐、风雨、脚步与日常互动</small></label><button class="action-button" data-sound>${settings.sound?'声音已开 · 静音':'开启声音'}</button></div><p class="audio-intro">晴天有鸟鸣，夜晚有虫声；屋檐下的雨、海边的浪和木地板上的脚步，各有自己的声音。首次点击后开始播放。</p>${[ ['master','总音量'],['music','背景音乐'],['ambience','环境声音'],['effects','动作与提示'] ].map(([key,label])=>`<div class="audio-volume"><label for="audio-${key}">${label}<output id="volume-${key}">${Math.round(settings.audio[key]*100)}%</output></label><input id="audio-${key}" type="range" data-volume="${key}" min="0" max="100" step="1" value="${Math.round(settings.audio[key]*100)}"></div>`).join('')}<div class="performance-readout">画面 ${metrics.fps??'—'} FPS · ${settings.mode==='3d'?'当前绘制 '+(metrics.calls??'—')+' 次':'省电画布模式'}<br>小镇按地区加载，只有当前地区会绘制。</div>`;
    if(data.active){html+=row('时间的脚步','暂停后可以慢慢看看风景。',`<button class="action-button" data-pause>${data.paused?'继续时间':'暂停时间'}</button>`);html+=row('存好这一刻','保存当前人生在此浏览器。','<button class="action-button" data-save>立即保存</button>');html+=row('给人生留一份副本','导出 JSON，可带到另一个浏览器。','<button class="action-button" data-export>导出存档</button>');html+=row('找回之前的日子','保留最近三次自动保存的备份。','<button class="action-button" data-backups>查看备份</button>');html+=row('回到人生手记','先保存，再返回选择其他人生。','<button class="action-button" data-title>保存并返回</button>');}
    html+=row('带回另一段人生','导入时会创建新副本，不覆盖已有角色。','<button class="action-button" data-import>导入存档</button>');html+=desc('进度保存在当前浏览器中。清除网站数据会移除存档，建议偶尔导出一份副本。');html+=divider('怎么在小镇生活')+desc('手机：拖动左下摇杆行走，右侧按钮互动<br>电脑：点击地面 / WASD 行走，E 互动 · Esc：关闭手记<br>B：背包 · M：地图 · R：邻里 · J：手记<br>空格：暂停时间 · 滚轮：拉近或拉远<br>右键拖动：旋转立体视角<br>一整天约 16 分钟；翻看手记与离线时暂停。');
  }
  if(kind==='backups'){title='把之前的日子找回来';caption='A FEW MOMENTS KEPT SAFE';html=desc('恢复前也会保留当前进度。最近三次成功保存，会留下备份。');for(const entry of data.entries??[]){const c=calendar(entry.state.day);html+=row('第 '+c.year+' 年 · '+SEASONS[c.season]+' '+c.date+' 日',clock(entry.state.minute)+' · '+new Date(entry.updatedAt).toLocaleString('zh-CN'),`<button class="action-button" data-restore="${esc(entry.key)}">恢复这一天</button>`);}if(!data.entries?.length)html+='<div class="empty-panel">再保存几次，就会留下可以回头看的日子。</div>';}
  return {title,caption,html};
}
